import React, {memo, useCallback, useMemo} from 'react';

import {List, getConfig} from '@gravity-ui/uikit';

import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import {cnTrackerSelect} from '../TrackerSelect.classname';
import {defaultMessages} from '../i18n';
import type {TrackerSelectItem, TrackerSelectItemValueBase} from '../types';

import {SelectItem} from './SelectItem';

export type SelectItemsProps<
    Value extends TrackerSelectItemValueBase = TrackerSelectItemValueBase,
> = {
    items: TrackerSelectItem<Value>[];
    className?: string;
    selectedItemsIds?: string[];
    disabledItemsIds?: string[];
    onItemClick?: (item: TrackerSelectItem<Value>) => void;
    itemHeight?: number;
    activeItemId?: string;
    onItemPin?: (id: string) => void;
    onItemUnpin?: (id: string) => void;
    itemClassName?: string;
} & Pick<
    Parameters<typeof SelectItem>[0],
    | 'renderItem'
    | 'renderInfo'
    | 'showArrowOnUnselectedItems'
    | 'hideCheckbox'
    | 'singleSelect'
    | 'groupId'
    | 'showMeta'
    | 'itemActions'
    | 'pinnable'
    | 'disableDefaultItemRender'
>;

const SelectItemsWrapped = <Value extends TrackerSelectItemValueBase>({
    items,
    selectedItemsIds,
    disabledItemsIds,
    onItemClick,
    onItemPin,
    onItemUnpin,
    itemActions,
    itemClassName,
    showMeta,
    showArrowOnUnselectedItems,
    hideCheckbox,
    singleSelect,
    itemHeight,
    className,
    activeItemId,
    renderItem: providedRenderItem,
    renderInfo,
    pinnable,
    groupId,
    disableDefaultItemRender,
}: SelectItemsProps<Value>) => {
    const config = getConfig();
    const {t} = useLocalizedString(defaultMessages, config.lang);
    const renderItem = useCallback(
        (item: TrackerSelectItem<Value>) => (
            <SelectItem
                item={item}
                renderItem={providedRenderItem}
                renderInfo={renderInfo}
                isSelected={selectedItemsIds?.includes(item.id)}
                isDisabled={disabledItemsIds?.includes(item.id)}
                hideCheckbox={hideCheckbox}
                itemActions={itemActions}
                pinnable={pinnable}
                onPin={onItemPin}
                onUnpin={onItemUnpin}
                groupId={groupId}
                disableDefaultItemRender={disableDefaultItemRender}
                showMeta={showMeta}
                showArrowOnUnselectedItems={showArrowOnUnselectedItems}
                singleSelect={singleSelect}
                active={activeItemId === item.id}
                onItemClick={
                    onItemClick as (item: TrackerSelectItem<TrackerSelectItemValueBase>) => void
                }
                itemClassName={itemClassName}
            />
        ),
        [
            providedRenderItem,
            renderInfo,
            selectedItemsIds,
            disabledItemsIds,
            hideCheckbox,
            itemActions,
            pinnable,
            onItemPin,
            onItemUnpin,
            groupId,
            disableDefaultItemRender,
            showMeta,
            showArrowOnUnselectedItems,
            singleSelect,
            activeItemId,
            onItemClick,
            itemClassName,
        ],
    );

    let defaultItemHeight = 36;

    if (showMeta) {
        defaultItemHeight += 12;
    }

    const listContent = useMemo(() => {
        if (items.length === 0) {
            return <div className={cnTrackerSelect('empty-text')}>{t('emptyList')}</div>;
        }

        return (
            <List
                className={cnTrackerSelect(
                    'select-items',
                    {'single-select': singleSelect},
                    className,
                )}
                filterable={false}
                items={items}
                renderItem={renderItem}
                virtualized={false}
                sortable={false}
                itemHeight={itemHeight ?? defaultItemHeight}
                itemClassName={itemClassName}
            />
        );
    }, [
        items,
        singleSelect,
        renderItem,
        className,
        itemHeight,
        itemClassName,
        defaultItemHeight,
        t,
    ]);

    return <>{listContent}</>;
};

export const SelectItems = memo(SelectItemsWrapped) as typeof SelectItemsWrapped;
